1 | import { Hono } from 'hono';
2 | import { z } from 'zod';
3 | import { driftFindings, incidents, invariants, mutations, simulations, tasks, workflows } from '../../store/index.js';
4 | import { eventBus } from '../../core/events/bus.js';
5 | import { approvalGate, loadContext, runToApproval, workflowEngine } from '../../core/weave/index.js';
6 | import { futuresSimulator } from '../../core/futures/simulator.js';
7 | import { HttpError, notFound, parseBody, queryInt } from '../http.js';
8 | import { streamEvents, type SseMessage } from '../routes/sse.js';
9 | import {
10 |   activeWorkflow,
11 |   activityEvent,
12 |   consoleDriftFinding,
13 |   consoleGraph,
14 |   consoleIncident,
15 |   consoleInvariant,
16 |   consoleMutation,
17 |   consoleScenario,
18 |   consoleWorkflow,
19 |   epochIndex,
20 |   specialistTask,
21 |   trajectorySnapshots,
22 |   trendData
23 | } from './views.js';
24 | 
25 | /**
26 |  * /api/v1: the console adapter. Every response uses the view models the
27 |  * console already renders (src/console/types on epoch-frontend), so switching
28 |  * from mock data to live data changes no component.
29 |  */
30 | export const consoleRoutes = new Hono();
31 | 
32 | consoleRoutes.get('/workflows/active', c => {
33 |   const workflow = activeWorkflow();
34 |   if (!workflow) throw new HttpError(404, 'No workflow has run yet; start one from Bob or the console');
35 |   return c.json(consoleWorkflow(workflow));
36 | });
37 | 
38 | consoleRoutes.get('/workflows', c => c.json(
39 |   workflows.listWorkflows({ limit: queryInt(c, 'limit', 20) }).filter(w => w.kind !== 'seed').map(consoleWorkflow)
40 | ));
41 | 
42 | consoleRoutes.get('/workflows/:id', c => {
43 |   const workflow = workflows.getWorkflow(c.req.param('id'));
44 |   if (!workflow) throw notFound(`Workflow ${c.req.param('id')}`);
45 |   return c.json(consoleWorkflow(workflow));
46 | });
47 | 
48 | consoleRoutes.post('/workflows', async c => {
49 |   const body = await parseBody(c, z.object({ requirement: z.string().trim().min(3), author: z.string().trim().min(1).default('console user'), auto: z.boolean().default(true) }));
50 |   const { workflow } = workflowEngine.start({ requirement: body.requirement, author: body.author, source: 'console' });
51 |   loadContext(workflow.workflow_id, body.author);
52 |   if (body.auto) runToApproval(workflow.workflow_id, body.author).catch(error => console.error(`Workflow ${workflow.workflow_id} stopped:`, error));
53 |   return c.json(consoleWorkflow(workflowEngine.require(workflow.workflow_id)), 201);
54 | });
55 | 
56 | consoleRoutes.post('/workflows/:id/decision', async c => {
57 |   const body = await parseBody(c, z.object({
58 |     decision: z.enum(['APPROVED', 'REJECTED']),
59 |     rationale: z.string().max(2000).optional(),
60 |     actor: z.string().trim().min(1).default('console reviewer')
61 |   }));
62 |   const result = await approvalGate.recordDecision(c.req.param('id'), body.actor, body.decision, body.rationale);
63 |   return c.json({ workflow: consoleWorkflow(workflowEngine.require(c.req.param('id'))), mutation: result.mutation ? consoleMutation(result.mutation) : null });
64 | });
65 | 
66 | consoleRoutes.get('/trajectory/snapshots', c => c.json(trajectorySnapshots()));
67 | 
68 | consoleRoutes.get('/trajectory/drift-findings', c => {
69 |   const activeOnly = c.req.query('activeOnly') === 'true';
70 |   return c.json(driftFindings.listDriftFindings(activeOnly ? { status: 'open' } : {}).map(consoleDriftFinding));
71 | });
72 | 
73 | consoleRoutes.get('/trajectory/graph', c => c.json(consoleGraph(queryInt(c, 'recent', 6))));
74 | 
75 | consoleRoutes.get('/trajectory/trend', c => c.json(trendData(queryInt(c, 'limit', 12))));
76 | 
77 | consoleRoutes.get('/mutations', c => {
78 |   const start = queryInt(c, 'epochStart');
79 |   const end = queryInt(c, 'epochEnd');
80 |   const component = c.req.query('component');
81 |   const list = mutations.listMutations({ component: component && component !== 'ALL' ? component : undefined })
82 |     .filter(m => (start === undefined || epochIndex(m.epoch_id) >= start) && (end === undefined || epochIndex(m.epoch_id) <= end));
83 |   return c.json(list.map(consoleMutation));
84 | });
85 | 
86 | consoleRoutes.get('/mutations/:id', c => {
87 |   const mutation = mutations.getMutation(c.req.param('id'));
88 |   if (!mutation) throw notFound(`Mutation ${c.req.param('id')}`);
89 |   return c.json(consoleMutation(mutation));
90 | });
91 | 
92 | consoleRoutes.get('/incidents', c => c.json(incidents.listIncidents().map(consoleIncident)));
93 | 
94 | consoleRoutes.get('/invariants', c => c.json(invariants.listInvariants().map(consoleInvariant)));
95 | 
96 | consoleRoutes.get('/simulations', c => {
97 |   const divergence = c.req.query('divergenceMutationId');
98 |   const list = simulations.listSimulations().filter(s => !divergence || s.base_mutation_id === divergence);
99 |   return c.json(list.flatMap(s => s.scenarios.map(scenario => consoleScenario(s, scenario))));
100 | });
101 | 
102 | consoleRoutes.post('/simulations/remediate', async c => {
103 |   const body = await parseBody(c, z.object({
104 |     scenarioId: z.string().regex(/^[A-Za-z0-9_-]+:[A-Za-z0-9_-]+$/, 'Use "<simulationId>:<scenarioId>" from GET /api/v1/simulations'),
105 |     author: z.string().trim().min(1).default('console reviewer'),
106 |     dryRun: z.boolean().default(false)
107 |   }));
108 |   const [simulationId, scenarioId] = body.scenarioId.split(':') as [string, string];
109 |   const simulation = simulations.getSimulation(simulationId);
110 |   const scenario = simulation?.scenarios.find(s => s.scenario_id === scenarioId);
111 |   if (!simulation || !scenario) throw notFound(`Scenario ${body.scenarioId}`);
112 |   if (body.dryRun) return c.json({ dryRun: true, scenario: consoleScenario(simulation, scenario), diff: scenario.diff ?? null });
113 |   if (scenario.status !== 'COMPLETED') throw new HttpError(409, `Scenario ${body.scenarioId} has not been measured yet`);
114 |   const { workflowId } = futuresSimulator.select(simulationId, scenarioId, body.author);
115 |   loadContext(workflowId, body.author);
116 |   return c.json({ workflowId, workflow: consoleWorkflow(workflowEngine.require(workflowId)) }, 201);
117 | });
118 | 
119 | consoleRoutes.get('/activity', c => {
120 |   const limit = queryInt(c, 'limit', 30) ?? 30;
121 |   return c.json(eventBus.recent().map(activityEvent).filter((e): e is NonNullable<typeof e> => e !== undefined).slice(-limit).reverse());
122 | });
123 | 
124 | consoleRoutes.route('/stream', streamEvents(event => {
125 |   const out: SseMessage[] = [];
126 |   const activity = activityEvent(event);
127 |   if (activity) out.push({ event: 'epoch.activity', data: activity });
128 |   const p = event.payload;
129 |   if (event.type === 'mutation.committed' && typeof p.mutationId === 'string') {
130 |     const m = mutations.getMutation(p.mutationId);
131 |     if (m) out.push({ event: 'epoch.mutation', data: consoleMutation(m) });
132 |   }
133 |   if ((event.type === 'drift.detected' || event.type === 'drift.resolved') && typeof p.findingId === 'string') {
134 |     const f = driftFindings.getDriftFinding(p.findingId);
135 |     if (f) out.push({ event: 'epoch.drift', data: consoleDriftFinding(f) });
136 |   }
137 |   if (event.type === 'invariant.changed' && typeof p.invariantId === 'string') {
138 |     const inv = invariants.getInvariant(p.invariantId);
139 |     if (inv) out.push({ event: 'epoch.invariant', data: consoleInvariant(inv) });
140 |   }
141 |   if ((event.type === 'task.started' || event.type === 'task.completed' || event.type === 'task.failed') && typeof p.taskId === 'string') {
142 |     const task = tasks.getTask(p.taskId);
143 |     if (task) out.push({ event: 'epoch.task', data: specialistTask(task, 0) });
144 |   }
145 |   if (event.type === 'workflow.updated' || event.type === 'approval.requested' || event.type === 'decision.recorded') {
146 |     out.push({ event: 'epoch.workflow', data: { workflowId: p.workflowId, type: event.type } });
147 |   }
148 |   return out;
149 | }));
150 | 
151 | export function registerConsoleRoutes(app: Hono): void {
152 |   app.route('/api/v1', consoleRoutes);
153 | }
