1 | import { pathToFileURL } from 'node:url';
2 | import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
3 | import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
4 | import type { CallToolResult } from '@modelcontextprotocol/sdk/types.js';
5 | import { z } from 'zod';
6 | 
7 | /**
8 |  * EPOCH-MCP (ADR-009, amended by ADR-026). A stdio MCP server that gives Bob
9 |  * EPOCH's longitudinal memory and lets Bob drive WEAVE workflows. It is a thin
10 |  * client of the EPOCH API, so every write shows up on the console's live
11 |  * stream. There is deliberately no approve tool: the human gate stays human.
12 |  */
13 | 
14 | const API = (process.env.EPOCH_API_URL ?? 'http://127.0.0.1:3000').replace(/\/$/, '');
15 | const AUTHOR = process.env.EPOCH_MCP_AUTHOR ?? 'IBM Bob';
16 | 
17 | async function call(method: 'GET' | 'POST', path: string, body?: unknown): Promise<unknown> {
18 |   let response: Response;
19 |   try {
20 |     response = await fetch(`${API}${path}`, {
21 |       method,
22 |       headers: { 'Content-Type': 'application/json' },
23 |       ...(body === undefined ? {} : { body: JSON.stringify(body) })
24 |     });
25 |   } catch {
26 |     throw new Error(`EPOCH API is not reachable at ${API}. Start it with "pnpm api:dev".`);
27 |   }
28 |   const text = await response.text();
29 |   const data = text.length > 0 ? (JSON.parse(text) as unknown) : {};
30 |   if (!response.ok) {
31 |     const message = typeof data === 'object' && data !== null && 'error' in data ? String((data as { error: unknown }).error) : response.statusText;
32 |     throw new Error(`${method} ${path} failed (${response.status}): ${message}`);
33 |   }
34 |   return data;
35 | }
36 | 
37 | function ok(summary: string, data?: unknown): CallToolResult {
38 |   const text = data === undefined ? summary : `${summary}\n\n${JSON.stringify(data, null, 2)}`;
39 |   return { content: [{ type: 'text', text }] };
40 | }
41 | 
42 | function fail(error: unknown): CallToolResult {
43 |   return { content: [{ type: 'text', text: error instanceof Error ? error.message : String(error) }], isError: true };
44 | }
45 | 
46 | async function run(fn: () => Promise<CallToolResult>): Promise<CallToolResult> {
47 |   try {
48 |     return await fn();
49 |   } catch (error) {
50 |     return fail(error);
51 |   }
52 | }
53 | 
54 | type Json = Record<string, unknown>;
55 | const asJson = (value: unknown): Json => (typeof value === 'object' && value !== null ? (value as Json) : {});
56 | 
57 | const READ_ONLY = { readOnlyHint: true, openWorldHint: false } as const;
58 | const WRITES = { readOnlyHint: false, destructiveHint: false, openWorldHint: false } as const;
59 | const SPECIALISTS = ['context', 'historian', 'security', 'qa', 'evolution', 'incident', 'synthesis'] as const;
60 | 
61 | export function createMcpServer(): McpServer {
62 |   const server = new McpServer({ name: 'epoch', version: '0.4.0' });
63 | 
64 |   // ── Longitudinal memory (read-only) ───────────────────────────────────────
65 | 
66 |   server.registerTool('get_trajectory_snapshot', {
67 |     title: 'Trajectory snapshot',
68 |     description: 'Current boundary integrity, coupling, envelope status, open drift findings, current epoch and invariant statuses of the watched system.',
69 |     annotations: READ_ONLY
70 |   }, () => run(async () => {
71 |     const { snapshot } = asJson(await call('GET', '/api/trajectory/snapshot'));
72 |     const s = asJson(snapshot);
73 |     return ok(`Boundary integrity ${s.boundaryIntegrityScore}, coupling ${s.couplingScore}, ${s.withinEnvelope ? 'inside' : 'OUTSIDE'} the envelope, ${s.openDriftFindings} open drift finding(s), epoch ${s.currentEpochId}.`, s);
74 |   }));
75 | 
76 |   server.registerTool('get_mutation_history', {
77 |     title: 'Mutation history',
78 |     description: 'Recent mutations (intent, author, touched components, trajectory delta), optionally for one component such as "disputes" or "ledger".',
79 |     inputSchema: { component: z.string().optional(), limit: z.number().int().min(1).max(50).default(10) },
80 |     annotations: READ_ONLY
81 |   }, ({ component, limit }) => run(async () => {
82 |     const query = new URLSearchParams({ limit: String(limit ?? 10) });
83 |     if (component) query.set('component', component);
84 |     const { mutations } = asJson(await call('GET', `/api/mutations?${query}`));
85 |     const list = (mutations as Json[]).map(m => ({ id: m.mutation_id, intent: m.intent, author: m.author, components: m.affected_components, epoch: m.epoch_id, delta: m.trajectory_delta }));
86 |     return ok(`${list.length} mutation(s)${component ? ` touching ${component}` : ''}, newest first.`, list);
87 |   }));
88 | 
89 |   server.registerTool('get_mutation', {
90 |     title: 'Mutation detail',
91 |     description: 'One mutation with its evidence, weakened invariants, related incidents, drift findings and diff.',
92 |     inputSchema: { mutation_id: z.string().regex(/^M-\d+$/) },
93 |     annotations: READ_ONLY
94 |   }, ({ mutation_id }) => run(async () => {
95 |     const detail = asJson(await call('GET', `/api/mutations/${mutation_id}`));
96 |     const diff = typeof detail.diff === 'string' ? detail.diff.slice(0, 4000) : null;
97 |     return ok(`${mutation_id}: ${String(asJson(detail.mutation).intent)}`, { ...detail, diff });
98 |   }));
99 | 
100 |   server.registerTool('check_invariants', {
101 |     title: 'Invariant status',
102 |     description: 'Machine-checked invariants with their status (HOLDING, WEAKENED, VIOLATED) and the scanner detail. Filter by components to see what a change could affect.',
103 |     inputSchema: { components: z.array(z.string()).optional() },
104 |     annotations: READ_ONLY
105 |   }, ({ components }) => run(async () => {
106 |     const { invariants } = asJson(await call('GET', '/api/invariants'));
107 |     const list = (invariants as Json[]).filter(i => !components || components.length === 0 || (i.scope_components as string[]).some(c => components.includes(c)));
108 |     return ok(list.map(i => `${i.invariant_id} ${i.status}: ${i.name}`).join('\n'), list.map(i => ({ id: i.invariant_id, name: i.name, status: i.status, scope: i.scope_components, detail: i.detail })));
109 |   }));
110 | 
111 |   server.registerTool('get_causal_chain', {
112 |     title: 'Causal archaeology',
113 |     description: 'Candidate causal chain for a drift finding, incident, invariant, mutation or free-text symptom. Returns ranked candidates with the earliest plausible mutation. Results are hypotheses, never proof.',
114 |     inputSchema: {
115 |       symptom: z.string().optional(),
116 |       finding_id: z.string().optional(),
117 |       incident_id: z.string().optional(),
118 |       invariant_id: z.string().optional(),
119 |       mutation_id: z.string().optional()
120 |     },
121 |     annotations: READ_ONLY
122 |   }, args => run(async () => {
123 |     const query = new URLSearchParams();
124 |     if (args.finding_id) query.set('finding', args.finding_id);
125 |     else if (args.incident_id) query.set('incident', args.incident_id);
126 |     else if (args.invariant_id) query.set('invariant', args.invariant_id);
127 |     else if (args.mutation_id) query.set('mutation', args.mutation_id);
128 |     else query.set('symptom', args.symptom ?? 'open drift');
129 |     const { chain } = asJson(await call('GET', `/api/graph/causal-chain?${query}`));
130 |     const c = asJson(chain);
131 |     const earliest = asJson(c.earliestPlausible);
132 |     const proximate = asJson(c.mostProximate);
133 |     return ok(
134 |       `Candidate causal chain for ${asJson(c.subject).id}: ${(c.chain as string[]).join(' → ') || 'none'}. ` +
135 |         `Earliest plausible: ${earliest.mutationId ?? 'none'} (${earliest.evidenceStatus ?? '-'}); most proximate: ${proximate.mutationId ?? 'none'} (${proximate.evidenceStatus ?? '-'}). ${c.language}`,
136 |       c
137 |     );
138 |   }));
139 | 
140 |   server.registerTool('list_drift_findings', {
141 |     title: 'Drift findings',
142 |     description: 'Boundary erosion, invariant weakening and dependency growth findings with severity, measurement and the mutations behind them.',
143 |     inputSchema: { status: z.enum(['open', 'resolved']).optional() },
144 |     annotations: READ_ONLY
145 |   }, ({ status }) => run(async () => {
146 |     const { findings } = asJson(await call('GET', `/api/drift${status ? `?status=${status}` : ''}`));
147 |     const list = findings as Json[];
148 |     return ok(list.map(f => `${f.finding_id} ${f.severity} ${f.status}: ${f.title}`).join('\n') || 'No drift findings.', list);
149 |   }));
150 | 
151 |   server.registerTool('list_active_workflows', {
152 |     title: 'Active workflows',
153 |     description: 'WEAVE workflows that have not completed or been rejected.',
154 |     annotations: READ_ONLY
155 |   }, () => run(async () => {
156 |     const { workflows } = asJson(await call('GET', '/api/workflows/active'));
157 |     const list = (workflows as Json[]).map(w => ({ id: w.workflow_id, title: w.title, kind: w.kind, status: w.status, stage: w.current_stage }));
158 |     return ok(`${list.length} active workflow(s).`, list);
159 |   }));
160 | 
161 |   server.registerTool('get_workflow_status', {
162 |     title: 'Workflow status',
163 |     description: 'Status, valid next transitions, task graph, evidence counts, decision and resulting mutation of a workflow.',
164 |     inputSchema: { workflow_id: z.string().min(1) },
165 |     annotations: READ_ONLY
166 |   }, ({ workflow_id }) => run(async () => {
167 |     const r = asJson(await call('GET', `/api/workflows/${workflow_id}`));
168 |     const wf = asJson(r.workflow);
169 |     const tasks = (r.tasks as Json[]).map(t => ({ agent: t.agent_type, status: t.status, claims: (t.evidence as unknown[]).length }));
170 |     const decision = (r.decisions as Json[]).at(-1);
171 |     const mutation = r.mutation ? asJson(r.mutation).mutation_id : null;
172 |     return ok(
173 |       `${workflow_id} is ${wf.status}${wf.current_stage ? ` (${wf.current_stage})` : ''}.` +
174 |         (decision ? ` Decision: ${decision.action} by ${decision.actor}.` : '') +
175 |         (mutation ? ` Recorded as ${mutation}.` : ''),
176 |       { status: wf.status, stage: wf.current_stage, validTransitions: r.validTransitions, tasks, decision: decision ?? null, mutation }
177 |     );
178 |   }));
179 | 
180 |   server.registerTool('get_context_bundle', {
181 |     title: 'Context bundle',
182 |     description: 'Requirement, acceptance criteria, relevant files, prior mutations, invariants in scope and provenance for a workflow.',
183 |     inputSchema: { workflow_id: z.string().min(1) },
184 |     annotations: READ_ONLY
185 |   }, ({ workflow_id }) => run(async () => {
186 |     const { context } = asJson(await call('GET', `/api/workflows/${workflow_id}/context`));
187 |     return ok(`Context bundle for ${workflow_id}.`, context);
188 |   }));
189 | 
190 |   server.registerTool('get_decision_package', {
191 |     title: 'Decision package',
192 |     description: 'What the human sees at the approval gate: risk, recommendation, open questions, measured improvements, trajectory preview and drift preview.',
193 |     inputSchema: { workflow_id: z.string().min(1) },
194 |     annotations: READ_ONLY
195 |   }, ({ workflow_id }) => run(async () => {
196 |     const { package: pkg } = asJson(await call('GET', `/api/workflows/${workflow_id}/decision-package`));
197 |     const p = asJson(pkg);
198 |     return ok(`Risk ${p.riskLevel}. ${p.recommendation}`, { ...p, evidenceByAgent: undefined });
199 |   }));
200 | 
201 |   server.registerTool('get_repo_status', {
202 |     title: 'Sample repository status',
203 |     description: 'Where the watched payments service lives on disk (edit files there), its HEAD commit and uncommitted changes.',
204 |     annotations: READ_ONLY
205 |   }, () => run(async () => {
206 |     const status = asJson(await call('GET', '/api/repo/status'));
207 |     return ok(`Edit the watched system in ${status.path}. HEAD ${String(status.head).slice(0, 7)}; ${(status.changedFiles as string[]).length} changed file(s).`, status);
208 |   }));
209 | 
210 |   // ── Driving WEAVE workflows (writes; Bob asks before each call) ──────────
211 | 
212 |   server.registerTool('start_workflow', {
213 |     title: 'Start a WEAVE workflow',
214 |     description: 'Record a requirement as an event and open a workflow. EPOCH assembles the context bundle; the workflow waits in PLANNING for record_plan.',
215 |     inputSchema: {
216 |       requirement: z.string().min(3),
217 |       title: z.string().optional(),
218 |       kind: z.enum(['feature', 'incident', 'remediation']).default('feature')
219 |     },
220 |     annotations: WRITES
221 |   }, ({ requirement, title, kind }) => run(async () => {
222 |     const r = asJson(await call('POST', '/api/workflows', { requirement, title, kind, author: AUTHOR, source: 'epoch-mcp' }));
223 |     const wf = asJson(r.workflow);
224 |     const ctx = asJson(r.context);
225 |     const repo = asJson(ctx.repository);
226 |     return ok(
227 |       `Workflow ${wf.workflow_id} is ${wf.status}. Relevant files: ${(repo.relevant_files as string[]).join(', ') || 'none found'}. ` +
228 |         `${(ctx.prior_mutations as unknown[]).length} prior mutation(s) and ${(ctx.invariants as unknown[]).length} invariant(s) in scope. Next: record_plan.`,
229 |       { workflow_id: wf.workflow_id, status: wf.status, context: ctx }
230 |     );
231 |   }));
232 | 
233 |   server.registerTool('record_plan', {
234 |     title: 'Record the plan',
235 |     description: 'Store Bob\'s plan for the workflow and create the specialist task graph. Moves the workflow to EXECUTING.',
236 |     inputSchema: { workflow_id: z.string().min(1), plan: z.string().min(1).max(20_000) },
237 |     annotations: WRITES
238 |   }, ({ workflow_id, plan }) => run(async () => {
239 |     const r = asJson(await call('POST', `/api/workflows/${workflow_id}/plan`, { actor: AUTHOR, plan }));
240 |     const layers = (asJson(r.plan).layers as Json[][]).map(l => l.map(t => t.agent).join(' ∥ '));
241 |     return ok(`Plan recorded; ${workflow_id} is EXECUTING. Specialist layers: ${layers.join(' → ')}.`, r.plan);
242 |   }));
243 | 
244 |   server.registerTool('run_specialist', {
245 |     title: 'Run an EPOCH specialist',
246 |     description: 'Run one of EPOCH\'s deterministic specialists (they measure; they do not guess) and record its claims as evidence. Use from a subagent: Historian, Security and QA can run in parallel.',
247 |     inputSchema: { workflow_id: z.string().min(1), agent: z.enum(SPECIALISTS) },
248 |     annotations: WRITES
249 |   }, ({ workflow_id, agent }) => run(async () => {
250 |     const r = asJson(await call('POST', `/api/workflows/${workflow_id}/specialists/${agent}`));
251 |     const claims = (r.evidence as Json[]).map(e => `[${e.status}${e.finding_severity ? `/${e.finding_severity}` : ''}] ${e.claim}`);
252 |     return ok(`${agent}: ${r.summary} (risk ${r.riskLevel})\n${claims.join('\n')}`);
253 |   }));
254 | 
255 |   server.registerTool('record_evidence', {
256 |     title: 'Record a claim',
257 |     description: 'Record Bob\'s own claim on the workflow. Use "observed" only for things you measured, "inferred" for conclusions and "hypothesised" for candidate explanations.',
258 |     inputSchema: {
259 |       workflow_id: z.string().min(1),
260 |       claim: z.string().min(3).max(4000),
261 |       status: z.enum(['observed', 'inferred', 'hypothesised']),
262 |       source_ref: z.string().min(1),
263 |       severity: z.enum(['info', 'low', 'medium', 'high', 'critical']).optional(),
264 |       subagent: z.string().default('bob')
265 |     },
