44 | export interface ListMutationsOptions {
45 |   component?: string | undefined;
46 |   epochId?: string | undefined;
47 |   limit?: number | undefined;
48 |   offset?: number | undefined;
49 |   /** 'desc' (default) returns the newest first. */
50 |   order?: 'asc' | 'desc' | undefined;
51 | }
52 | 
53 | export function listMutations(options: ListMutationsOptions = {}): Mutation[] {
54 |   const conditions: string[] = [];
55 |   const params: unknown[] = [];
56 | 
57 |   if (options.component) {
58 |     conditions.push('EXISTS (SELECT 1 FROM json_each(mutations.affected_components) WHERE json_each.value = ?)');
59 |     params.push(options.component);
60 |   }
61 |   if (options.epochId) {
62 |     conditions.push('epoch_id = ?');
63 |     params.push(options.epochId);
64 |   }
65 | 
66 |   const direction = options.order === 'asc' ? 'ASC' : 'DESC';
67 |   let sql = 'SELECT * FROM mutations';
68 |   if (conditions.length > 0) sql += ` WHERE ${conditions.join(' AND ')}`;
69 |   sql += ` ORDER BY ${SEQUENCE_ORDER} ${direction} LIMIT ? OFFSET ?`;
70 |   params.push(options.limit ?? -1, options.offset ?? 0);
71 | 
72 |   return (getDb().prepare(sql).all(...params) as Row[]).map(toMutation);
73 | }
74 | 
75 | /** Highest numeric mutation sequence recorded so far (M-1041 → 1041), or 0. */
