60 | /**
61 |  * Mutations reachable backwards from a mutation through FOLLOWS edges,
62 |  * nearest first, bounded by depth (recursive CTE, ARCHITECTURE §13).
63 |  */
64 | export function ancestorMutations(mutationId: string, maxDepth: number): Array<{ mutation_id: string; depth: number }> {
65 |   return getDb().prepare(`
66 |     WITH RECURSIVE ancestors(mutation_id, depth) AS (
67 |       SELECT from_id, 1 FROM graph_edges WHERE to_id = ? AND relationship = 'FOLLOWS'
68 |       UNION
69 |       SELECT e.from_id, a.depth + 1
70 |       FROM graph_edges e JOIN ancestors a ON e.to_id = a.mutation_id
71 |       WHERE e.relationship = 'FOLLOWS' AND a.depth < ?
72 |     )
73 |     SELECT mutation_id, MIN(depth) AS depth FROM ancestors GROUP BY mutation_id ORDER BY depth ASC
74 |   `).all(mutationId, maxDepth) as Array<{ mutation_id: string; depth: number }>;
75 | }
