17 | async function call(method: 'GET' | 'POST', path: string, body?: unknown): Promise<unknown> {
18 |   let response: Response;
19 |   try {
20 |     response = await fetch(`${API}${path}`, {
21 |       method,
22 |       headers: { 'Content-Type': 'application/json' },
23 |       ...(body === undefined ? {} : { body: JSON.stringify(body) })
24 |     });
25 |   } catch {
26 |     throw new Error(`EPOCH API is not reachable at ${API}. Start it with "pnpm api:dev".`);
27 |   }
28 |   const text = await response.text();
29 |   const data = text.length > 0 ? (JSON.parse(text) as unknown) : {};
30 |   if (!response.ok) {
31 |     const message = typeof data === 'object' && data !== null && 'error' in data ? String((data as { error: unknown }).error) : response.statusText;
32 |     throw new Error(`${method} ${path} failed (${response.status}): ${message}`);
33 |   }
34 |   return data;
35 | }
