7 | /**
8 |  * EPOCH-MCP (ADR-009, amended by ADR-026). A stdio MCP server that gives Bob
9 |  * EPOCH's longitudinal memory and lets Bob drive WEAVE workflows. It is a thin
10 |  * client of the EPOCH API, so every write shows up on the console's live
11 |  * stream. There is deliberately no approve tool: the human gate stays human.
12 |  */
13 | 
14 | const API = (process.env.EPOCH_API_URL ?? 'http://127.0.0.1:3000').replace(/\/$/, '');
15 | const AUTHOR = process.env.EPOCH_MCP_AUTHOR ?? 'IBM Bob';
16 | 
17 | async function call(method: 'GET' | 'POST', path: string, body?: unknown): Promise<unknown> {
18 |   let response: Response;
19 |   try {
20 |     response = await fetch(`${API}${path}`, {
21 |       method,
22 |       headers: { 'Content-Type': 'application/json' },
23 |       ...(body === undefined ? {} : { body: JSON.stringify(body) })
24 |     });
25 |   } catch {
26 |     throw new Error(`EPOCH API is not reachable at ${API}. Start it with "pnpm api:dev".`);
27 |   }
28 |   const text = await response.text();
29 |   const data = text.length > 0 ? (JSON.parse(text) as unknown) : {};
30 |   if (!response.ok) {
31 |     const message = typeof data === 'object' && data !== null && 'error' in data ? String((data as { error: unknown }).error) : response.statusText;
32 |     throw new Error(`${method} ${path} failed (${response.status}): ${message}`);
33 |   }
34 |   return data;
35 | }
36 | 
37 | function ok(summary: string, data?: unknown): CallToolResult {
38 |   const text = data === undefined ? summary : `${summary}\n\n${JSON.stringify(data, null, 2)}`;
39 |   return { content: [{ type: 'text', text }] };
40 | }
41 | 
42 | function fail(error: unknown): CallToolResult {
43 |   return { content: [{ type: 'text', text: error instanceof Error ? error.message : String(error) }], isError: true };
44 | }
45 | 
46 | async function run(fn: () => Promise<CallToolResult>): Promise<CallToolResult> {
47 |   try {
48 |     return await fn();
49 |   } catch (error) {
50 |     return fail(error);
51 |   }
52 | }
