200 |   const weakened = edges.filter(e => e.relationship === 'WEAKENS' && e.from_id === m.mutation_id).map(e => e.to_id);
201 |   const openIncident = incidents.listIncidents().find(i => i.status !== 'resolved' && (i.candidate_mutations ?? []).includes(m.mutation_id));
202 |   const compensated = mutations.listMutations().some(x => x.compensates_mutation_id === m.mutation_id);
203 |   const failingProbes = (scan?.probes ?? []).filter(p => !p.ok);
204 |   const transitions = m.trajectory_delta.invariantChanges.map(c => `${c.invariant_id} ${c.previousStatus}→${c.newStatus}`);
205 |   const diff = mutationEngine.mutationDiff(m.mutation_id);
206 | 
207 |   const contribution: ConsoleMutation['structuralConsequences']['driftContribution'] =
208 |     findings.some(f => f.severity === 'critical') ? 'CRITICAL'
209 |       : findings.length > 0 ? 'MODERATE'
210 |         : weakened.length > 0 ? 'SIGNIFICANT'
211 |           : m.trajectory_delta.couplingDelta > 0 ? 'LOW'
212 |             : 'NONE';
213 | 
214 |   const out: ConsoleMutation = {
215 |     id: m.mutation_id,
216 |     title: shortTitle(m.intent),
217 |     intent: m.intent,
218 |     timestamp: iso(m.created_at),
219 |     epoch: epochIndex(m.epoch_id),
220 |     author: m.author ?? 'unknown',
