233 |         `Boundary integrity ${m.trajectory_delta.boundaryIntegrityDelta >= 0 ? '+' : ''}${m.trajectory_delta.boundaryIntegrityDelta.toFixed(3)}, coupling ${m.trajectory_delta.couplingDelta >= 0 ? '+' : ''}${m.trajectory_delta.couplingDelta.toFixed(3)}`
234 |       ].filter(Boolean).join('. '),
